// Shown only when the bundled release is newer than what this install has
// already acknowledged. String compare is safe: ids are ISO dates.

engine.whatsNewUnseen:
function whatsNewUnseen(lastSeenId, release) {
  if (!release || !release.id) return false;
  if (!lastSeenId) return true;
  return String(lastSeenId) < String(release.id);
}

view.renderWhatsNew:
function renderWhatsNew(opts) {
  opts = opts || {};
  var release = opts.release || {};
  var onClose = typeof opts.onClose === "function" ? opts.onClose : function () {};
  var onFeatured = typeof opts.onFeatured === "function" ? opts.onFeatured : null;

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  var improved = release.improved || [];
  var fixed = release.fixed || [];
  var newCount = release.featured ? 1 : 0;
  var changeCount = improved.length + fixed.length;

  var ov = document.createElement("div");
  ov.className = "_eli3_wn_overlay";
  ov.style.cssText =
    "position: fixed; inset: 0; z-index: 9600;" +
    "background: rgba(8, 17, 28, 0.58);" +
    "display: flex; align-items: center; justify-content: center;" +
    "padding: 14px; box-sizing: border-box;" +
    "font-family: Inter, system-ui, sans-serif;";

  var SECTION_LABEL =
    "font-size: 9px; font-weight: 800; color: #90a4ae;" +
    "text-transform: uppercase; letter-spacing: 1.4px; margin-bottom: 9px;";

  var featuredHtml = "";
  if (release.featured) {
    var f = release.featured;
    featuredHtml =
      '<div class="_eli3_wn_rise" style="animation-delay:.12s; padding: 16px 16px 4px;">' +
        '<div style="' + SECTION_LABEL + '">Worth a try</div>' +
        '<div style="border:1px solid #c9a227; background:linear-gradient(180deg,#fffdf5 0%,#fef3c7 100%); padding:14px;">' +
          '<div style="display:flex; align-items:flex-start; gap:11px;">' +
            '<div style="flex:0 0 38px; height:38px; background:#6b4f0a; color:#ffd97a;' +
              'display:flex; align-items:center; justify-content:center; font-size:19px;">' + esc(f.icon) + '</div>' +
            '<div style="flex:1; min-width:0;">' +
              '<div style="display:flex; align-items:center; gap:7px; margin-bottom:3px;">' +
                '<span style="font-size:14px; font-weight:800; color:#3f2f05;">' + esc(f.name) + '</span>' +
                '<span class="_eli3_wn_pulse" style="font-size:8px; font-weight:800; color:#6b4f0a;' +
                  'background:#ffe9a8; border:1px solid #c9a227; padding:2px 6px; letter-spacing:1px;">NEW</span>' +
              '</div>' +
              '<div style="font-size:12.5px; color:#5c4708; line-height:1.55;">' + esc(f.desc) + '</div>' +
              (f.where
                ? '<div style="font-size:11px; color:#8a6710; line-height:1.5; margin-top:7px; font-style:italic;">' + esc(f.where) + '</div>'
                : '') +
            '</div>' +
          '</div>' +
          '<button data-wn-featured style="margin-top:12px; width:100%; height:34px; border-radius:0;' +
            'cursor:pointer; font-size:10px; font-weight:800; letter-spacing:1px; text-transform:uppercase;' +
            'color:#ffffff; background:linear-gradient(to bottom,#8a6710 0%,#6b4f0a 100%);' +
            'border:1px solid #5a4208; box-shadow:inset 0 1px 0 rgba(255,255,255,0.18);">' +
            esc(f.cta || "Open") + '</button>' +
        '</div>' +
      '</div>';
  }

  function rowsHtml(list, startDelay, tickColor) {
    return list.map(function (row, i) {
      var d = startDelay + i * 0.06;
      return '<div class="_eli3_wn_rise" style="animation-delay:' + d.toFixed(2) + 's;' +
          'display:flex; gap:10px; align-items:flex-start; padding:8px 0; border-bottom:1px solid #f0f2f4;">' +
          '<div class="_eli3_wn_tick" style="animation-delay:' + (d + 0.12).toFixed(2) + 's;' +
            'flex:0 0 16px; height:16px; margin-top:1px; background:' + tickColor + '; color:#ffffff;' +
            'display:flex; align-items:center; justify-content:center; font-size:10px; font-weight:800;">✓</div>' +
          '<div style="flex:1; min-width:0; font-size:12.5px; color:#37474f; line-height:1.5;">' +
            '<span style="font-weight:800; color:#1565c0;">' + esc(row.tool) + '</span> · ' + esc(row.text) +
          '</div>' +
        '</div>';
    }).join("");
  }

  ov.innerHTML =
    '<div class="_eli3_wn_pop" data-wn-dialog style="' +
      'display:flex; flex-direction:column; box-sizing:border-box;' +
      'width:100%; max-width:440px; max-height:88vh;' +
      'background:#ffffff; border:1px solid #0d1b2a; border-radius:0;' +
      'box-shadow:0 18px 48px rgba(0,0,0,0.42);">' +

      '<div style="position:relative; overflow:hidden; flex:0 0 auto;' +
        'background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);' +
        'border-bottom:3px solid #c9a227; padding:18px 18px 16px;">' +
        '<div style="position:absolute; inset:0; pointer-events:none; overflow:hidden;">' +
          '<div class="_eli3_wn_sweep" style="position:absolute; top:0; bottom:0; width:44%;' +
            'background:linear-gradient(100deg,transparent,rgba(201,162,39,0.22),transparent);"></div>' +
        '</div>' +
        '<button data-wn-x aria-label="Close" style="position:absolute; top:10px; right:10px; z-index:3;' +
          'width:24px; height:24px; padding:0; cursor:pointer; border-radius:0;' +
          'background:rgba(255,255,255,0.12); border:1px solid rgba(255,255,255,0.28);' +
          'color:#cfd8dc; font-size:13px; line-height:1;">✕</button>' +
        '<div style="position:relative;">' +
          '<div style="font-size:8px; font-weight:700; color:#c9a227; text-transform:uppercase;' +
            'letter-spacing:2.5px; margin-bottom:6px;">Updated · ' + esc(release.dateLabel || "") + '</div>' +
          '<div style="font-family:Georgia,serif; font-size:23px; color:#ffffff;' +
            'letter-spacing:0.3px; line-height:1.15;">' + esc(release.greeting || "Welcome back") + '.</div>' +
          '<div style="font-size:12px; color:#8fa6c7; margin-top:6px; line-height:1.5;">' +
            'ELI picked up <b style="color:#e8eef7;">' + newCount + ' new tool</b> and ' +
            '<b style="color:#e8eef7;">' + changeCount + ' changes</b> while you were away.</div>' +
        '</div>' +
      '</div>' +

      '<div data-wn-scroll style="flex:1 1 auto; min-height:0; overflow-y:auto; overflow-x:hidden;' +
        '-webkit-overflow-scrolling:touch;">' +
        featuredHtml +
        (improved.length
          ? '<div class="_eli3_wn_rise" style="animation-delay:.2s; padding:16px 16px 6px;">' +
              '<div style="' + SECTION_LABEL + '">Better now</div>' +
              rowsHtml(improved, 0.26, "#1565c0") +
            '</div>'
          : '') +
        (fixed.length
          ? '<div class="_eli3_wn_rise" style="animation-delay:.28s; padding:16px 16px 6px;">' +
              '<div style="' + SECTION_LABEL + '">Fixed for you</div>' +
              rowsHtml(fixed, 0.34, "#2e7d32") +
            '</div>'
          : '') +
        '<div style="height:14px;"></div>' +
      '</div>' +

      '<div style="flex:0 0 auto; padding:12px 16px; border-top:1px solid #e4e8eb; background:#fafbfc;">' +
        '<button data-wn-close style="width:100%; height:38px; border-radius:0; cursor:pointer;' +
          'font-size:10px; font-weight:800; letter-spacing:1px; text-transform:uppercase; color:#1a2327;' +
          'background:linear-gradient(to bottom,#f7f9fa 0%,#dce3e8 100%);' +
          'border:1px solid #b0bec5; border-top:1px solid #cfd8dc;' +
          'box-shadow:inset 0 1px 0 #ffffff, 0 1px 2px rgba(0,0,0,0.08);">Got it — take me in</button>' +
      '</div>' +
    '</div>';

  function onKey(e) {
    if (e.key === "Escape" || e.keyCode === 27) close();
  }

  function close() {
    document.removeEventListener("keydown", onKey, true);
    if (ov.parentNode) ov.parentNode.removeChild(ov);
    onClose();
  }

  ["[data-wn-close]", "[data-wn-x]"].forEach(function (sel) {
    var b = ov.querySelector(sel);
    if (b) b.onclick = close;
  });
  // Backdrop click dismisses; clicks inside the dialog must not.
  ov.onclick = function (e) { if (e.target === ov) close(); };

  var featBtn = ov.querySelector("[data-wn-featured]");
  if (featBtn) {
    featBtn.onclick = function () {
      close();
      if (onFeatured) onFeatured();
    };
  }

  document.addEventListener("keydown", onKey, true);
  document.body.appendChild(ov);
  return { close: close, el: ov };
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["whats_new"];
  if (!bundle) return;
  var whatsNewRelease = bundle._eliEngineFns && bundle._eliEngineFns.whatsNewRelease;
  var whatsNewUnseen = bundle._eliEngineFns && bundle._eliEngineFns.whatsNewUnseen;
  var renderWhatsNew = bundle._eliViewFns && bundle._eliViewFns.renderWhatsNew;
  if (!whatsNewRelease || !whatsNewUnseen || !renderWhatsNew) {
    eli.log.event("tool", "whats_new_init_missing_fns", {
      release: !!whatsNewRelease, unseen: !!whatsNewUnseen, render: !!renderWhatsNew,
    });
    return;
  }

  var SEEN_KEY = "whats_new_last_seen";

  function _openFeatured(release) {
    var ch = release && release.featured && release.featured.channel;
    if (!ch) return;
    try { eli.dispatch(ch, "open", { from: "whats_new" }); }
    catch (e) { eli.log.event("tool", "whats_new_featured_failed", { channel: ch, msg: e && e.message }); }
  }

  function _markSeen(id) {
    return eli.storage.put("config", { key: SEEN_KEY, value: id })
      .catch(function (e) {
        // Not silent: a failed write means the screen returns every boot.
        eli.log.event("tool", "whats_new_mark_seen_failed", { msg: e && e.message });
      });
  }

  function _show(release, markOnClose) {
    renderWhatsNew({
      release: release,
      onClose: function () { if (markOnClose) _markSeen(release.id); },
      onFeatured: function () { _openFeatured(release); },
    });
  }

  // Re-openable on demand (dashboard tile) without touching the marker.
  eli.register({
    tile: { app_whats_new: function () { _show(whatsNewRelease(), false); } },
    whats_new: { open: function () { _show(whatsNewRelease(), false); } },
  });

  // A missing marker means one of two very different things: a brand-new
  // install, or an established one receiving this tool for the first time.
  // Every existing user is in the second group on the release that ships
  // this tool — silently stamping them all would skip the very release it
  // exists to announce. Onboarding tells them apart.
  function _isEstablished() {
    return eli.storage.get("config", "onboarding_completed")
      .then(function (row) { return !!(row && row.value); })
      .catch(function () { return false; });
  }

  var release = whatsNewRelease();
  eli.storage.get("config", SEEN_KEY)
    .then(function (row) {
      var lastSeen = row && row.value ? row.value : null;
      if (!whatsNewUnseen(lastSeen, release)) return;
      if (lastSeen) return _show(release, true);
      return _isEstablished().then(function (established) {
        // Brand-new user: stamp silently rather than greeting them with a
        // change log for changes they never had.
        if (!established) return _markSeen(release.id);
        _show(release, true);
      });
    })
    .catch(function (e) {
      eli.log.event("tool", "whats_new_check_failed", { msg: e && e.message });
    });
}

jsonTools.css:
/* tools/whats_new/style.css — keyframes only. Everything else is inline
   on the element so the screen paints without depending on this file. */

@keyframes _eli3_wn_rise {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: none; }
}
@keyframes _eli3_wn_sweep {
  0%        { transform: translateX(-120%); }
  55%, 100% { transform: translateX(220%); }
}
@keyframes _eli3_wn_pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(201, 162, 39, 0.55); }
  50%      { box-shadow: 0 0 0 5px rgba(201, 162, 39, 0); }
}
@keyframes _eli3_wn_tick {
  from { opacity: 0; transform: scale(0.4); }
  to   { opacity: 1; transform: none; }
}
@keyframes _eli3_wn_pop {
  from { opacity: 0; transform: translateY(14px) scale(0.97); }
  to   { opacity: 1; transform: none; }
}

._eli3_wn_pop { animation: _eli3_wn_pop .34s cubic-bezier(.2,.9,.3,1) both; }

._eli3_wn_rise  { animation: _eli3_wn_rise .5s cubic-bezier(.2,.7,.3,1) both; }
._eli3_wn_tick  { animation: _eli3_wn_tick .35s cubic-bezier(.2,1.4,.4,1) both; }
._eli3_wn_sweep { animation: _eli3_wn_sweep 2.8s ease-in-out .4s infinite; }
._eli3_wn_pulse { animation: _eli3_wn_pulse 2s ease-in-out infinite; }

/* Respect the OS setting — a takeover screen is the worst place to force
   motion on someone who asked for none. */
@media (prefers-reduced-motion: reduce) {
  ._eli3_wn_rise,
  ._eli3_wn_tick,
  ._eli3_wn_sweep,
  ._eli3_wn_pulse,
  ._eli3_wn_pop {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}
